 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    # The three-cell color key lies along the top edge. Each key color
    # grows downward; an edge marker of that color creates a horizontal arm
    # and terminates the downward arm at its row.
    for c, color in enumerate(grid[0]):
        if color == 0:
            continue
        marker_rows = []
        for r in range(1, h):
            if grid[r][0] == color:
                marker_rows.append((r, 0))
            if grid[r][w - 1] == color:
                marker_rows.append((r, w - 1))
        if marker_rows:
            for r, edge_c in marker_rows:
                lo, hi = sorted((c, edge_c))
                for cc in range(lo, hi + 1):
                    out[r][cc] = color
            stop = max(r for r, _ in marker_rows)
        else:
            stop = h - 1
        for r in range(1, stop + 1):
            out[r][c] = color
    return out

